<script setup lang="ts">
import { computed, nextTick, onMounted, ref, watch } from 'vue'
import AppIcon from '@/components/ui/AppIcon.vue'
import CharacterIcon from '@/components/ui/CharacterIcon.vue'
import { useCharacterStore } from '@/stores/characters'
import type { ChatMessage, Group, GroupMember } from '@/types/group'
import { dayLabel, formatClock } from '@/utils/time'
const props = defineProps<{ group: Group; alert: string | null }>()
const emit = defineEmits<{ close: []; send: [text: string] }>()
const characters = useCharacterStore()
const draft = ref('')
const scroller = ref<HTMLElement | null>(null)
const liked = ref<Record<string, boolean>>({})
const online = computed(() => props.group.members.filter(m => m.isOnline).length)
const completed = computed(() => props.group.members.filter(m => m.checkedInToday).length)
const quickReplies = ['¡Listo por hoy!', '¿Cómo van?', '¡Buen avance!']
interface Row { message: ChatMessage; author: GroupMember | undefined; showDay: boolean; showHeader: boolean }
const rows = computed<Row[]>(() => {
  let previous: ChatMessage | undefined
  return props.group.messages.map(message => {
    const showDay = !previous || dayLabel(previous.sentAt) !== dayLabel(message.sentAt)
    const same = previous?.kind === 'user' && message.kind === 'user' && previous.authorId === message.authorId && new Date(message.sentAt).getTime() - new Date(previous.sentAt).getTime() < 300000
    previous = message
    return { message, author: props.group.members.find(m => m.id === message.authorId), showDay, showHeader: showDay || !same }
  })
})
async function scrollBottom() { await nextTick(); if (scroller.value) scroller.value.scrollTop = scroller.value.scrollHeight }
function submit() { const text = draft.value.trim(); if (!text) return; emit('send', text); draft.value = '' }
watch(() => props.group.messages.length, scrollBottom)
watch(() => props.group.id, () => { draft.value = ''; scrollBottom() })
onMounted(scrollBottom)
</script>
<template><section class="chat">
<header class="chat-head"><span class="chat-emblem"><AppIcon name="message" :size="22" /></span><div class="chat-title"><h3>Campamento</h3><span><i></i>{{ online }} en línea · {{ group.members.length }} miembros</span></div><button class="icon-button" aria-label="Cerrar chat" @click="emit('close')"><AppIcon name="x" :size="17" /></button></header>
<div class="team-checks"><div class="camp-avatars"><CharacterIcon v-for="m in group.members.slice(0, 5)" :key="m.id" :character="characters.forMember(m.id, m.isCurrentUser)" :size="26" /></div><span><AppIcon name="check" :size="13" />{{ completed }}/{{ group.members.length }} hoy</span></div>
<div v-if="alert" class="alert"><AppIcon name="bell" :size="15" /><p>{{ alert }}</p></div>
<div ref="scroller" class="messages" role="log" aria-label="Mensajes del equipo" aria-live="polite" aria-relevant="additions text"><p v-if="!rows.length" class="empty-chat">Aún no hay mensajes.</p><template v-for="row in rows" :key="row.message.id"><div v-if="row.showDay" class="day-sep"><span>{{ dayLabel(row.message.sentAt) }}</span></div><div v-if="row.message.kind === 'system'" class="system-msg"><span><AppIcon name="shield" :size="18" /></span><p>{{ row.message.text }}</p></div><article v-else class="msg" :class="{ mine: row.author?.isCurrentUser, grouped: !row.showHeader }"><div class="avatar-slot"><CharacterIcon v-if="row.showHeader" :character="characters.forMember(row.author?.id ?? 'guest', row.author?.isCurrentUser)" :size="28" /></div><div class="message-body"><div v-if="row.showHeader" class="meta"><strong>{{ row.author?.isCurrentUser ? 'Tú' : row.author?.name ?? 'Miembro' }}</strong><span v-if="row.author?.role === 'ADMIN'" class="leader">ADMIN</span></div><p class="bubble">{{ row.message.text }}</p><div class="message-foot"><time :datetime="row.message.sentAt">{{ formatClock(row.message.sentAt) }}</time><button class="reaction" :class="{ reacted: liked[row.message.id] }" :aria-label="liked[row.message.id] ? 'Quitar mi apoyo' : 'Apoyar mensaje'" :aria-pressed="!!liked[row.message.id]" @click="liked[row.message.id] = !liked[row.message.id]"><AppIcon name="heart" :size="12" /><span v-if="liked[row.message.id]">1</span></button></div></div></article></template></div>
<div class="quick-replies"><button v-for="reply in quickReplies" :key="reply" @click="draft = reply">{{ reply }}</button></div><form class="composer" @submit.prevent="submit"><label class="sr-only" :for="`chat-input-${group.id}`">Mensaje al equipo</label><input :id="`chat-input-${group.id}`" v-model="draft" maxlength="500" autocomplete="off" placeholder="Mensaje al equipo…" /><button class="send" type="submit" :disabled="!draft.trim()" aria-label="Enviar mensaje"><AppIcon name="send" :size="19" /></button></form>
</section></template>
<style scoped>
.chat{height:100%;min-height:0;display:flex;flex-direction:column;background:#1e1b28;color:#eee5f6}.chat-head{display:flex;align-items:center;gap:11px;padding:19px 16px;background:#342741;border-bottom:2px solid #53405f}.chat-emblem{display:grid;place-items:center;width:41px;height:43px;background:#aa83cc;border:2px solid #d5b5eb;border-bottom:4px solid #73518c;border-radius:12px;color:#291a35;transform:rotate(-5deg)}.chat-title{flex:1}.chat-title h3{font-size:17px;margin:0 0 6px;letter-spacing:-.02em}.chat-title>span{display:flex;align-items:center;gap:5px;font-size:9px;color:#cbb5dc}.chat-title i{width:5px;height:5px;background:#b8d69b;border-radius:50%}.icon-button{width:28px;height:30px;background:#281c34;color:#d9c0ee;border:1px solid #6c4d7d;border-bottom:3px solid #180f21;border-radius:7px;display:grid;place-items:center}.team-checks{display:flex;align-items:center;justify-content:space-between;padding:13px 18px;background:#272031;border-bottom:1px solid #43334e;gap:12px}.camp-avatars{display:flex;padding-left:5px;gap:3px}.camp-avatars>*{margin-left:-5px}.team-checks>span{display:flex;align-items:center;gap:5px;font-size:9px;color:#c4d7a8;background:#34402e;border:1px solid #526443;padding:5px 8px;border-radius:6px}.alert{display:flex;gap:8px;align-items:flex-start;padding:12px 15px;background:#40302a;color:#ead0a0;font-size:10px;border-bottom:1px solid #69503a}.alert p{margin:0;line-height:1.6}.alert svg{flex-shrink:0}.messages{flex:1;min-height:0;overflow-y:auto;padding:4px 16px 17px;display:flex;flex-direction:column;scrollbar-color:#695276 #201928}.day-sep{display:flex;align-items:center;gap:8px;margin:17px 0 9px;font-size:9px;text-transform:capitalize;color:#ac96be}.day-sep:before,.day-sep:after{content:'';height:1px;background:#44344f;flex:1}.day-sep span{background:#2b2235;border:1px solid #493451;border-radius:5px;padding:4px 7px}.system-msg{align-self:center;display:flex;align-items:center;gap:9px;margin:8px 0;padding:11px;background:#303b2c;border:1px solid #536848;border-bottom:3px solid #1a2617;border-radius:9px;color:#cdddba;max-width:100%}.system-msg>span{color:#d6c58a;flex-shrink:0}.system-msg p{font-size:10px;line-height:1.6;margin:0;overflow-wrap:anywhere}.msg{display:flex;align-items:flex-start;gap:10px;max-width:95%;margin-top:13px}.msg.grouped{margin-top:4px}.avatar-slot{width:28px;flex-shrink:0;padding-top:4px}.message-body{min-width:0;flex:1}.meta{display:flex;align-items:center;gap:6px;margin:0 0 6px}.meta strong{font-size:10px;font-weight:700;color:#d4b9e9}.leader{font-size:6px;background:#51412e;color:#e3ca94;border:1px solid #75603d;padding:2px 3px;border-radius:3px}.bubble{font-size:12px;line-height:1.7;padding:11px 13px;margin:0;background:#352a41;border:1px solid #604570;border-bottom:3px solid #171020;border-radius:3px 13px 13px 13px;color:#ede1f6;white-space:pre-wrap;overflow-wrap:anywhere}.msg.mine{align-self:flex-end;flex-direction:row-reverse}.mine .meta{justify-content:flex-end}.mine .bubble{background:#654b7c;border-color:#a17bba;border-bottom-color:#332140;border-radius:13px 3px 13px 13px}.message-foot{display:flex;align-items:center;gap:8px;justify-content:flex-end;margin:4px 0}.message-foot time{font-size:8px;color:#b5a0c4}.reaction{display:inline-flex;align-items:center;gap:3px;border:0;border-radius:5px;background:none;color:#a88dbb;padding:3px;font-size:8px}.reaction:hover,.reaction.reacted{color:#f1b1c3;background:#4f3048}.reaction.reacted svg{fill:#e6a1b4}.quick-replies{display:flex;gap:6px;overflow-x:auto;padding:11px 12px 5px;border-top:1px solid #493451;flex-shrink:0}.quick-replies button{border:1px solid #684979;border-bottom:3px solid #1a1024;background:#36263f;color:#d8bce9;border-radius:7px;padding:6px;font-size:8px;white-space:nowrap}.quick-replies button:hover{background:#4d355b}.composer{display:flex;gap:8px;align-items:center;padding:10px 12px 14px}.composer input{flex:1;min-width:0;border:1px solid #715180;border-bottom:3px solid #100a18;border-radius:9px;background:#15101d;color:#f3e8fc;font-size:11px;padding:13px 11px;outline-offset:2px}.composer input::placeholder{color:#a48bb7}.send{width:42px;height:43px;display:grid;place-items:center;background:#b4d58b;border:1px solid #daecb7;border-bottom:4px solid #687e4e;border-radius:10px;color:#2e4229;transition:transform .15s}.send:enabled:hover{transform:translateY(-2px);background:#c8e5a3}.send:disabled{background:#43364e;border-color:#655171;color:#9983a8;cursor:default}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.empty-chat{font-size:11px;color:#b7a3c6;text-align:center;padding:25px}.chat button:focus-visible,.chat input:focus-visible{outline:2px solid #e0bdff;outline-offset:2px}
</style>
